import { render } from "@react-email/render";
import DigestEmail from "@repo/email/templates/digest";
import { MongoClient, ObjectId, type WithId } from "mongodb";

const { MONGODB_URI } = process.env;
if (!MONGODB_URI) {
  console.error("MONGODB_URI environment variable is required");
  process.exit(1);
}

const client = new MongoClient(MONGODB_URI);
const db = client.db();
const digests = db.collection("digests");

// Same shape the email templates use: NEXT_PUBLIC_APEX_URL is a bare
// hostname, so the scheme is ours to add.
const baseUrl = process.env.NEXT_PUBLIC_APEX_URL
  ? `https://${process.env.NEXT_PUBLIC_APEX_URL}`
  : "https://hastoggle.dev";

/** The fields of `Subscriber` a send actually reads. */
interface DigestRecipient {
  email: string;
  emailVerified: Date | null;
  unsubscribeToken: string | null;
}

const [, , command, ...args] = process.argv;

async function handleCreate() {
  const title = args[0] || "Untitled Draft";
  const result = await digests.insertOne({
    content: "",
    createdAt: new Date(),
    misconception: "",
    scheduledFor: null,
    sentAt: null,
    status: "draft",
    title,
    updatedAt: new Date(),
  });
  console.log(`Created digest: ${result.insertedId}`);
}

function parseUpdateFlags(): Record<string, unknown> {
  const updates: Record<string, unknown> = { updatedAt: new Date() };
  for (let i = 1; i < args.length; i += 2) {
    const flag = args[i];
    const value = args[i + 1];
    switch (flag) {
      case "--title":
        updates.title = value;
        break;
      case "--misconception":
        updates.misconception = value;
        break;
      case "--content":
        updates.content = value;
        break;
      case "--series-name":
        updates["series.name"] = value;
        break;
      case "--series-part":
        updates["series.part"] = Number.parseInt(value, 10);
        break;
      default:
        break;
    }
  }
  return updates;
}

async function handleUpdate() {
  const [id] = args;
  if (!id) {
    console.error(
      "Usage: bun digest update <id> --title '...' --misconception '...' --content '...' --series-name '...' --series-part N"
    );
    process.exit(1);
  }

  const updates = parseUpdateFlags();
  await digests.updateOne({ _id: new ObjectId(id) }, { $set: updates });
  console.log(`Updated digest: ${id}`);
}

async function handleSchedule() {
  const [id, dateStr] = args;
  if (!id) {
    console.error("Usage: bun digest schedule <id> [YYYY-MM-DDTHH:mm]");
    process.exit(1);
  }

  const scheduledFor = dateStr ? new Date(dateStr) : getNextMonday();
  await digests.updateOne(
    { _id: new ObjectId(id) },
    {
      $set: {
        scheduledFor,
        status: "scheduled",
        updatedAt: new Date(),
      },
    }
  );
  console.log(`Scheduled digest ${id} for ${scheduledFor.toISOString()}`);
}

async function handleList() {
  const allDigests = await digests.find({}).sort({ createdAt: -1 }).toArray();

  if (allDigests.length === 0) {
    console.log("No digests found.");
    return;
  }

  for (const d of allDigests) {
    const series = d.series ? ` [${d.series.name} #${d.series.part}]` : "";
    const scheduled = d.scheduledFor
      ? ` → ${d.scheduledFor.toISOString().split("T")[0]}`
      : "";
    console.log(
      `${d._id} | ${d.status.padEnd(9)} | ${d.title}${series}${scheduled}`
    );
  }
}

async function handleSend() {
  const [id] = args;
  if (!id) {
    console.error("Usage: bun digest send <id>");
    process.exit(1);
  }

  const digest = await digests.findOne({ _id: new ObjectId(id) });
  if (!digest) {
    console.error(`Digest ${id} not found`);
    process.exit(1);
  }

  if (digest.status === "sent") {
    console.error(`Digest ${id} has already been sent`);
    process.exit(1);
  }

  const { Resend } = await import("resend");
  const resend = new Resend(process.env.RESEND_TOKEN);

  const subscribers = await db
    .collection<DigestRecipient>("subscribers")
    .find({ emailVerified: { $ne: null } })
    .toArray();

  // A digest with no working unsubscribe link is the one thing the privacy
  // policy promises against, so a tokenless row is skipped rather than sent
  // a dead link. Only rows confirmed before the token was minted can be in
  // this state; re-confirming mints one.
  const recipients = subscribers.filter(
    (s): s is WithId<DigestRecipient> & { unsubscribeToken: string } =>
      Boolean(s.unsubscribeToken)
  );
  const tokenless = subscribers.length - recipients.length;
  if (tokenless > 0) {
    console.warn(
      `Skipping ${tokenless} subscriber(s) with no unsubscribe token.`
    );
  }

  if (recipients.length === 0) {
    console.log("No verified subscribers to send to.");
    return;
  }

  console.log(`Sending to ${recipients.length} subscribers...`);

  const resendFrom = process.env.RESEND_FROM ?? "noreply@hastoggle.dev";

  // Rendered per recipient, not once for the batch: the unsubscribe link
  // carries that subscriber's durable token.
  const messages = await Promise.all(
    recipients.map(async (subscriber) => ({
      from: resendFrom,
      html: await render(
        DigestEmail({
          content: digest.content,
          misconception: digest.misconception,
          series: digest.series,
          title: digest.title,
          unsubscribeUrl: `${baseUrl}/api/unsubscribe?token=${encodeURIComponent(
            subscriber.unsubscribeToken
          )}`,
        })
      ),
      subject: digest.title,
      to: subscriber.email,
    }))
  );

  const { error } = await resend.batch.send(messages);

  if (error) {
    console.error("Failed to send:", error);
    process.exit(1);
  }

  await digests.updateOne(
    { _id: new ObjectId(id) },
    {
      $set: {
        sentAt: new Date(),
        status: "sent",
        updatedAt: new Date(),
      },
    }
  );

  console.log(`Sent digest ${id} to ${recipients.length} subscribers`);
}

function printHelp() {
  console.log("Usage: bun digest <create|update|schedule|list|send>");
  console.log("");
  console.log("Commands:");
  console.log("  create [title]                    Create a draft digest");
  console.log("  update <id> --title '...' ...     Update digest fields");
  console.log("  schedule <id> [datetime]          Schedule for sending");
  console.log("  list                              List all digests");
  console.log("  send <id>                         Send to subscribers");
}

async function main() {
  try {
    await client.connect();

    switch (command) {
      case "create":
        await handleCreate();
        break;
      case "update":
        await handleUpdate();
        break;
      case "schedule":
        await handleSchedule();
        break;
      case "list":
        await handleList();
        break;
      case "send":
        await handleSend();
        break;
      default:
        printHelp();
    }
  } finally {
    await client.close();
  }
}

function getNextMonday(): Date {
  const now = new Date();
  const day = now.getDay();
  const daysUntilMonday = day === 0 ? 1 : 8 - day;
  const nextMonday = new Date(now);
  nextMonday.setDate(now.getDate() + daysUntilMonday);
  nextMonday.setHours(9, 0, 0, 0);
  return nextMonday;
}

main();
